class LRUCache:
    """A class implementing an LRU (Least Recently Used) cache using a hashmap and a buffer list to track access order, ensuring O(1) get and put operations."""

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.access_order = []

    def get(self, key: int) -> int:
        """Retrieves the value from the cache if the key exists, otherwise returns -1."""
        if key in self.cache:
            value = self.cache[key]
            self.access_order.remove(key)
            self.access_order.append(key)
            return value
        return -1

    def put(self, key: int, value: int) -> None:
        """Inserts or updates the value in the cache for the given key."""
        if key in self.cache:
            self.cache[key] = value
            self.access_order.remove(key)
            self.access_order.append(key)
        else:
            if len(self.cache) >= self.capacity:
                lru_key = self.access_order.pop(0)
                del self.cache[lru_key]
            self.cache[key] = value
            self.access_order.append(key)

class LRUCache:
    """A class implementing an LRU (Least Recently Used) cache using a hashmap and a fixed-size circular buffer for O(1) access time."""

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.values = [None] * capacity
        self.index = 0
        self.size = 0

    def get(self, key: int) -> int:
        """Retrieves the value from the cache if the key exists, otherwise returns -1."""
        if key in self.cache:
            return self.cache[key][0]
        return -1

    def put(self, key: int, value: int) -> None:
        """Inserts or updates the value in the cache for the given key."""
        if key in self.cache:
            self.cache[key][0] = value
            return

        if self.size < self.capacity:
            self.values[self.index] = key
            self.cache[key] = [value, self.index]
            self.index = (self.index + 1) % self.capacity
            self.size += 1
        else:
            lru_key = self.values[self.index]
            del self.cache[lru_key]
            self.values[self.index] = key
            self.cache[key] = [value, self.index]
            self.index = (self.index + 1) % self.capacity
